using Microsoft.Extensions.DependencyInjection;
using SolidOps.UM.Domain;

namespace SolidOps.UM.Application;

public partial class TeamService
{
    // a team with members has exactly one owner, and each member is an existing user, once
    private async partial Task<Error?> CheckMembersAsync(Team aggregate, CancellationToken cancellationToken)
    {
        var members = aggregate.Members;
        if (members.Count == 0)
        {
            return null;
        }

        var errors = new Dictionary<string, string[]>();
        if (members.Count(x => x.IsOwner) != 1)
        {
            errors["Members"] = ["A team with members must have exactly one owner."];
        }

        var users = Services.GetRequiredService<IUserRepository>();
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        for (var i = 0; i < members.Count; i++)
        {
            var email = members[i].UserEmail;
            var path = $"Members[{i}].UserEmail";
            if (!seen.Add(email))
            {
                errors[path] = ["This user is already a member of the team."];
            }
            else if (await users.FindByEmailAsync(email, cancellationToken) is null)
            {
                errors[path] = ["No user has this email."];
            }
        }

        return errors.Count > 0 ? Error.Invalid(errors) : null;
    }

    private Task<Error?> CheckNoMembersCoreAsync(Team aggregate)
    {
        return Task.FromResult<Error?>(aggregate.Members.Count > 0 ? Error.Conflict("The team still has members.") : null);
    }

    private partial Task<Error?> CheckNoMembersAsync(Team aggregate, CancellationToken cancellationToken)
    {
        return CheckNoMembersCoreAsync(aggregate);
    }
}
