using System.Net;
using System.Net.Http.Json;
using SolidOps.UM.Application;

namespace SolidOps.UM.Tests;

[TestClass]
public sealed class TeamTests : ApiTestBase
{
    [TestMethod]
    public async Task TeamGoesThroughTheWholeCrudWithItsMembers()
    {
        await NewUsersAsync("ada@example.com", "bob@example.com", "cy@example.com");

        var created = await PostAsync<TeamDto>("/teams", Team("core", Member("ada@example.com", true), Member("bob@example.com")));
        Assert.HasCount(2, created.Members);
        Assert.IsTrue(created.Members.All(x => x.Id != Guid.Empty));

        var ada = created.Members.Single(x => x.UserEmail == "ada@example.com");
        var update = Team("core2", new TeamMemberInput { Id = ada.Id, UserEmail = "ada@example.com", IsOwner = false }, Member("cy@example.com", true));
        var response = await Client.PutAsJsonAsync($"/teams/{created.Id}", update);
        Assert.AreEqual(HttpStatusCode.OK, response.StatusCode, await response.Content.ReadAsStringAsync());
        var updated = (await response.Content.ReadFromJsonAsync<TeamDto>())!;
        Assert.AreEqual("core2", updated.Name);
        CollectionAssert.AreEquivalent(new[] { "ada@example.com", "cy@example.com" }, updated.Members.Select(x => x.UserEmail).ToArray());
        Assert.AreEqual(ada.Id, updated.Members.Single(x => x.UserEmail == "ada@example.com").Id);

        var read = await Client.GetFromJsonAsync<TeamDto>($"/teams/{created.Id}");
        Assert.HasCount(2, read!.Members);

        // members removed, then the team can go
        Assert.AreEqual(HttpStatusCode.OK, (await Client.PutAsJsonAsync($"/teams/{created.Id}", Team("core2"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.NoContent, (await Client.DeleteAsync($"/teams/{created.Id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.GetAsync($"/teams/{created.Id}")).StatusCode);
    }

    [TestMethod]
    public async Task TeamWithoutMembersIsAllowed()
    {
        var team = await PostAsync<TeamDto>("/teams", Team("empty"));
        Assert.IsEmpty(team.Members);
    }

    [TestMethod]
    public async Task TeamsArePaged()
    {
        foreach (var name in new[] { "c", "a", "b" })
        {
            await PostAsync<TeamDto>("/teams", Team(name));
        }

        var page = await Client.GetFromJsonAsync<Page<TeamDto>>("/teams?orderBy=Name&page=2&pageSize=2");

        Assert.AreEqual(3, page!.TotalCount);
        Assert.AreEqual("c", page.Items.Single().Name);
    }

    [TestMethod]
    public async Task UnknownTeamIsNotFound()
    {
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.PutAsJsonAsync($"/teams/{Guid.NewGuid()}", Team("x"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.DeleteAsync($"/teams/{Guid.NewGuid()}")).StatusCode);
    }

    [TestMethod]
    public async Task NameAndDescriptionAreValidated()
    {
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", Team("")), "Name");
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", Team(new string('n', 51))), "Name");
        var team = Team("described");
        team.Description = new string('d', 201);
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", team), "Description");
        team.Description = new string('d', 200);
        Assert.AreEqual(HttpStatusCode.Created, (await Client.PostAsJsonAsync("/teams", team)).StatusCode);
    }

    [TestMethod]
    public async Task MemberEmailIsValidated()
    {
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", Team("t", Member("", true))), "Members[0].UserEmail");
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", Team("t", Member(new string('a', 51), true))), "Members[0].UserEmail");
    }

    [TestMethod]
    public async Task MemberMustBeAnExistingUser()
    {
        var response = await Client.PostAsJsonAsync("/teams", Team("ghosts", Member("nobody@example.com", true)));

        await AssertInvalidAsync(response, "Members[0].UserEmail");
    }

    [TestMethod]
    public async Task TeamWithMembersNeedsExactlyOneOwner()
    {
        await NewUsersAsync("ada@example.com", "bob@example.com");

        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", Team("none", Member("ada@example.com"))), "Members");
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", Team("two", Member("ada@example.com", true), Member("bob@example.com", true))), "Members");

        var team = await PostAsync<TeamDto>("/teams", Team("one", Member("ada@example.com", true)));
        var noOwner = Team("one", new TeamMemberInput { Id = team.Members[0].Id, UserEmail = "ada@example.com", IsOwner = false });
        await AssertInvalidAsync(await Client.PutAsJsonAsync($"/teams/{team.Id}", noOwner), "Members");
    }

    [TestMethod]
    public async Task SameEmailTwiceInATeamIsInvalid()
    {
        await NewUsersAsync("ada@example.com");

        var response = await Client.PostAsJsonAsync("/teams", Team("dup", Member("ada@example.com", true), Member("ada@example.com")));

        await AssertInvalidAsync(response, "Members[1].UserEmail");
    }

    [TestMethod]
    public async Task SameUserCanBeInSeveralTeams()
    {
        await NewUsersAsync("ada@example.com");

        await PostAsync<TeamDto>("/teams", Team("one", Member("ada@example.com", true)));
        await PostAsync<TeamDto>("/teams", Team("two", Member("ada@example.com", true)));
    }

    [TestMethod]
    public async Task TeamNameIsUnique()
    {
        await PostAsync<TeamDto>("/teams", Team("same"));

        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.PostAsJsonAsync("/teams", Team("same"))).StatusCode);

        var other = await PostAsync<TeamDto>("/teams", Team("other"));
        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.PutAsJsonAsync($"/teams/{other.Id}", Team("same"))).StatusCode);
    }

    [TestMethod]
    public async Task TeamWithMembersCannotBeDeleted()
    {
        await NewUsersAsync("ada@example.com");
        var team = await PostAsync<TeamDto>("/teams", Team("busy", Member("ada@example.com", true)));

        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.DeleteAsync($"/teams/{team.Id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync($"/teams/{team.Id}")).StatusCode);
    }

    [TestMethod]
    public async Task ReadingNeedsAuthenticationAndWritingNeedsManageTeams()
    {
        var team = await PostAsync<TeamDto>("/teams", Team("secured"));

        Unauthenticate();
        Assert.AreEqual(HttpStatusCode.Unauthorized, (await Client.GetAsync("/teams")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Unauthorized, (await Client.GetAsync($"/teams/{team.Id}")).StatusCode);

        AuthenticateAs(UMRights.ManageUsers);
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync("/teams")).StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync($"/teams/{team.Id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.PostAsJsonAsync("/teams", Team("denied"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.PutAsJsonAsync($"/teams/{team.Id}", Team("denied"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.DeleteAsync($"/teams/{team.Id}")).StatusCode);

        AuthenticateAs(UMRights.ManageTeams);
        Assert.AreEqual(HttpStatusCode.Created, (await Client.PostAsJsonAsync("/teams", Team("allowed"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.NoContent, (await Client.DeleteAsync($"/teams/{team.Id}")).StatusCode);
    }

    private async Task NewUsersAsync(params string[] emails)
    {
        foreach (var email in emails)
        {
            await PostAsync<UserDto>("/users", new UserInput { Email = email, Provider = "local" });
        }
    }

    private static TeamMemberInput Member(string email, bool isOwner = false) => new() { UserEmail = email, IsOwner = isOwner };

    private static TeamInput Team(string name, params TeamMemberInput[] members) => new() { Name = name, Members = [.. members] };
}
